import { Alert, ScrollView, StyleSheet, Text, TextInput, View } from "react-native";
import Slider from "@react-native-community/slider";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { apiFetch, jsonMutation } from "@/api";
import { Button, Card, ErrorState, Header, Screen } from "@/components";
import { useMobileBranding } from "@/branding";
import { colors } from "@/theme";
import { defaultWeights, goalkeeperWeightKeys, lineWeightKeys, updateWeight, weightTotalPercent, type WeightKey, type Weights } from "@/weights";

const lineFields=[{key:"speedWeight",label:"Físico",help:"Fôlego, velocidade e intensidade durante toda a partida."},{key:"skillWeight",label:"Técnica",help:"Passe, domínio, drible, finalização e qualidade com a bola."},{key:"tacticalIntelligenceWeight",label:"Inteligência Tática",help:"Ocupação de espaços, leitura de jogo e tomada de decisão."},{key:"markingWeight",label:"Marcação",help:"Desarme, posicionamento defensivo e recomposição."},{key:"competitivenessWeight",label:"Competitividade",help:"Entrega, raça, disputa de bolas e comprometimento."}] as const;
const goalkeeperFields=[{key:"goalkeeperDefensesWeight",label:"Defesas",help:"Reflexo, tempo de reação, defesas à queima-roupa e consistência."},{key:"goalkeeperPositioningWeight",label:"Posicionamento",help:"Leitura da jogada, colocação no gol, saída do gol e cobertura de ângulos."},{key:"goalkeeperSafetyWeight",label:"Segurança",help:"Firmeza nas defesas, retenção da bola, saídas em cruzamentos e baixo índice de falhas."},{key:"goalkeeperFootworkWeight",label:"Jogo com os Pés",help:"Qualidade na reposição, passes curtos e lançamentos, participação na saída de bola."},{key:"goalkeeperLeadershipWeight",label:"Liderança",help:"Organização da defesa, orientação aos companheiros e comando da linha defensiva."}] as const;

export default function ConfigScreen(){
 const {palette}=useMobileBranding(),client=useQueryClient(),query=useQuery({queryKey:["mobile-config"],queryFn:()=>apiFetch<Weights>("/api/mobile/config")}),[edited,setEdited]=useState<Weights|null>(null),weights=edited||(query.data?{...defaultWeights,...query.data,ratingSystemVersion:2}:null);
 const mutation=useMutation({mutationFn:(value:Weights)=>apiFetch("/api/mobile/config",jsonMutation("PUT",value)),onSuccess:()=>{client.invalidateQueries({queryKey:["mobile-config"]});client.invalidateQueries({queryKey:["profile"]});setEdited(null);Alert.alert("Tudo certo","Pesos atualizados com sucesso.")},onError:(error:Error)=>Alert.alert("Não foi possível salvar",error.message)});
 if(query.isError)return <Screen><Header title="Pesos do algoritmo"/><ErrorState message={(query.error as Error).message} retry={()=>query.refetch()}/></Screen>;
 const change=(key:WeightKey,percent:number)=>setEdited(updateWeight(weights||defaultWeights,key,Math.max(0,Math.min(100,percent))/100));
 const lineTotal=weights?weightTotalPercent(weights,lineWeightKeys):0,goalkeeperTotal=weights?weightTotalPercent(weights,goalkeeperWeightKeys):0,valid=lineTotal===100&&goalkeeperTotal===100;
 const save=()=>{if(!weights)return;if(!valid){Alert.alert("Revise os totais","Os pesos de jogadores de linha e goleiros precisam somar exatamente 100% em cada grupo.");return}Alert.alert("Salvar novos pesos?","A mudança será usada nas próximas escalações; partidas já salvas não serão alteradas.",[{text:"Cancelar",style:"cancel"},{text:"Salvar",onPress:()=>mutation.mutate(weights)}])};
 return <Screen><Header eyebrow="ADMINISTRAÇÃO" title="Pesos do algoritmo"/><ScrollView keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator={false} contentContainerStyle={styles.content}><Text style={[styles.intro,{color:palette.muted}]}>Ajuste cada peso de forma independente pelo número ou pelo controle deslizante. Para salvar, cada grupo deve totalizar 100%.</Text>{weights?<><WeightSection title="Jogadores de linha" subtitle="Critérios aplicados aos jogadores de linha" marker="LINHA" fields={lineFields} keys={lineWeightKeys} weights={weights} change={change}/><WeightSection title="Goleiros" subtitle="Critérios específicos para goleiros" marker="GOL" fields={goalkeeperFields} keys={goalkeeperWeightKeys} weights={weights} change={change}/><View style={styles.save}><Text style={[styles.saveHint,{color:valid?palette.green:colors.danger}]}>{valid?"Os dois grupos estão prontos para salvar.":"Ajuste os dois totais para 100% antes de salvar."}</Text><Button title="Salvar pesos" busy={mutation.isPending} disabled={!valid} onPress={save}/></View></>:null}</ScrollView></Screen>;
}
function WeightSection({title,subtitle,marker,fields,keys,weights,change}:any){
 const {palette}=useMobileBranding(),total=weightTotalPercent(weights,keys),valid=total===100,difference=Math.abs(100-total);
 return <Card style={styles.section}><View style={styles.sectionHead}><View style={[styles.marker,{backgroundColor:`${palette.green}16`}]}><Text style={[styles.markerText,{color:palette.green}]}>{marker}</Text></View><View style={styles.sectionCopy}><Text style={[styles.sectionTitle,{color:palette.text}]}>{title}</Text><Text style={[styles.sectionSubtitle,{color:palette.muted}]}>{subtitle}</Text></View><View style={[styles.total,{backgroundColor:valid?`${palette.green}12`:colors.dangerSoft}]}><Text style={[styles.totalValue,{color:valid?palette.green:colors.danger}]}>{total}%</Text><Text style={[styles.totalLabel,{color:valid?palette.green:colors.danger}]}>TOTAL</Text></View></View><Text accessibilityRole={valid?undefined:"alert"} style={[styles.totalHint,{color:valid?palette.green:colors.danger}]}>{valid?"Total correto. Este grupo está pronto.":total<100?`Faltam ${difference}% para completar 100%.`:`Reduza ${difference}% para voltar a 100%.`}</Text><View>{fields.map((field:any,index:number)=><View key={field.key} style={[styles.weight,index>0&&{borderTopColor:palette.border,borderTopWidth:1}]}><View style={styles.weightHead}><View style={styles.weightCopy}><Text style={[styles.weightTitle,{color:palette.text}]}>{field.label}</Text><Text numberOfLines={1} ellipsizeMode="tail" style={[styles.weightHelp,{color:palette.muted}]}>{field.help}</Text></View><View style={styles.percent}><TextInput accessibilityLabel={`Peso de ${field.label}`} keyboardType="number-pad" maxLength={3} selectTextOnFocus value={String(Math.round(Number(weights[field.key]??0)*100))} onChangeText={value=>change(field.key,Number(value.replace(/\D/g,"")))} style={[styles.input,{color:palette.text,borderColor:palette.border,backgroundColor:palette.cream}]}/><Text style={[styles.percentSign,{color:palette.text}]}>%</Text></View></View><Slider style={styles.slider} accessibilityLabel={`Ajustar peso de ${field.label}`} minimumValue={0} maximumValue={1} step={.01} value={Number(weights[field.key]??0)} onValueChange={value=>change(field.key,value*100)} minimumTrackTintColor={palette.green} maximumTrackTintColor={palette.border} thumbTintColor={palette.green}/></View>)}</View></Card>;
}

const styles=StyleSheet.create({
 content:{padding:20,paddingTop:4,paddingBottom:30,gap:14},intro:{fontSize:13,lineHeight:19,marginBottom:2},section:{padding:0,overflow:"hidden"},sectionHead:{flexDirection:"row",alignItems:"center",gap:10,padding:14,paddingBottom:12},marker:{width:43,height:43,borderRadius:13,alignItems:"center",justifyContent:"center"},markerText:{fontSize:10,fontWeight:"900",letterSpacing:.7},sectionCopy:{flex:1,minWidth:0},sectionTitle:{fontSize:19,fontWeight:"900"},sectionSubtitle:{fontSize:11,marginTop:3},total:{minWidth:58,borderRadius:12,paddingHorizontal:9,paddingVertical:6,alignItems:"center"},totalValue:{fontSize:17,fontWeight:"900"},totalLabel:{fontSize:7,fontWeight:"900",letterSpacing:.8,marginTop:1},totalHint:{fontSize:11,fontWeight:"800",paddingHorizontal:14,paddingBottom:8},weight:{paddingHorizontal:14,paddingVertical:9},weightHead:{flexDirection:"row",alignItems:"center",gap:10},weightCopy:{flex:1,minWidth:0},weightTitle:{fontSize:15,fontWeight:"800"},weightHelp:{fontSize:11,lineHeight:15,marginTop:2},percent:{flexDirection:"row",alignItems:"center",gap:4},input:{width:50,minHeight:36,borderWidth:1,borderRadius:9,paddingHorizontal:7,paddingVertical:5,textAlign:"center",fontSize:16,fontWeight:"800"},percentSign:{fontSize:13,fontWeight:"900"},slider:{height:28,marginHorizontal:-2,marginTop:1},save:{paddingTop:2,gap:8},saveHint:{fontSize:11,fontWeight:"800",textAlign:"center"}
});
